{
  "title": "School Enrolment and Infrastructure Dashboard",
  "subtitle": "Tracking enrolment trends, gender parity, and infrastructure gaps across schools",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total Students (2024)",
      "sql": "SELECT SUM(COALESCE(\"Girls 2024\", 0) + COALESCE(\"Boys 2024\", 0)) AS total_students FROM \"school_enrolment_by_year\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Girls Share in 2024",
      "sql": "SELECT ROUND(100.0 * SUM(COALESCE(\"Girls 2024\", 0)) / NULLIF(SUM(COALESCE(\"Girls 2024\", 0) + COALESCE(\"Boys 2024\", 0)), 0), 1) AS girls_share FROM \"school_enrolment_by_year\"",
      "unit": "%"
    },
    {
      "id": "p3",
      "kind": "kpi",
      "title": "Schools with Functional Girls' Toilets",
      "sql": "SELECT COUNT(*) AS toilet_count FROM \"school_infrastructure\" WHERE \"Toilets functional (girls)\" = 'Yes'",
      "unit": ""
    },
    {
      "id": "p4",
      "kind": "line",
      "title": "Enrolment Trend by Gender (2022-2024)",
      "sql": "WITH yearly_totals AS (\n  SELECT \n    '2022' AS year,\n    SUM(COALESCE(\"Girls 2022\", 0)) AS girls,\n    SUM(COALESCE(\"Boys 2022\", 0)) AS boys\n  FROM \"school_enrolment_by_year\"\n  UNION ALL\n  SELECT \n    '2023' AS year,\n    SUM(COALESCE(\"Girls 2023\", 0)) AS girls,\n    SUM(COALESCE(\"Boys 2023\", 0)) AS boys\n  FROM \"school_enrolment_by_year\"\n  UNION ALL\n  SELECT \n    '2024' AS year,\n    SUM(COALESCE(\"Girls 2024\", 0)) AS girls,\n    SUM(COALESCE(\"Boys 2024\", 0)) AS boys\n  FROM \"school_enrolment_by_year\"\n)\nSELECT year, girls, boys FROM yearly_totals ORDER BY year",
      "x": "year",
      "y": ["girls", "boys"]
    },
    {
      "id": "p5",
      "kind": "bar",
      "title": "Infrastructure Gaps by School",
      "sql": "SELECT \n  \"School Code\",\n  CASE WHEN \"Toilets functional (girls)\" = 'No' THEN 1 ELSE 0 END AS missing_toilets,\n  CASE WHEN \"Drinking water\" = 'No' THEN 1 ELSE 0 END AS missing_water,\n  CASE WHEN \"Electricity\" = 'No' THEN 1 ELSE 0 END AS missing_electricity\nFROM \"school_infrastructure\"\nORDER BY missing_toilets DESC, missing_water DESC, missing_electricity DESC\nLIMIT 20",
      "x": "School Code",
      "y": ["missing_toilets", "missing_water", "missing_electricity"]
    },
    {
      "id": "p6",
      "kind": "table",
      "title": "Top 10 Schools by Total Enrolment (2024)",
      "sql": "SELECT \n  \"School Name\",\n  \"Block\",\n  COALESCE(\"Girls 2024\", 0) AS girls_2024,\n  COALESCE(\"Boys 2024\", 0) AS boys_2024,\n  COALESCE(\"Girls 2024\", 0) + COALESCE(\"Boys 2024\", 0) AS total_2024\nFROM \"school_enrolment_by_year\"\nWHERE COALESCE(\"Girls 2024\", 0) + COALESCE(\"Boys 2024\", 0) > 0\nORDER BY total_2024 DESC\nLIMIT 10"
    }
  ],
  "narrative": "The dashboard shows a total of {{p1}} students enrolled in 2024, with girls making up {{p2}}% of the student population. This indicates progress toward gender parity in education.\n\nOver the years, enrolment trends reveal steady growth for both genders, though the gap between boys and girls remains a focus area for intervention.\n\nInfrastructure gaps persist, with only {{p3}} schools having functional toilets for girls. Access to drinking water and electricity also varies significantly across schools.\n\nAddressing these gaps is critical to improving retention and learning outcomes, especially for girls who may face additional barriers due to inadequate facilities."
}

{
  "title": "SHG Loan Repayment & Purpose Analysis",
  "subtitle": "Overview of loan repayment status, overdue amounts, and distribution by purpose",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total Loans Disbursed",
      "sql": "SELECT COUNT(*) AS n FROM \"shg_loan_register\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
