    {
      "id": "p3",
      "kind": "kpi",
      "title": "Overdue Loan Count",
      "sql": "SELECT COUNT(*) AS n FROM \"shg_loan_register\" WHERE \"Repayment Status\" = 'Overdue'",
      "unit": ""
    },
    {
      "id": "p4",
      "kind": "bar",
      "title": "Loans by Repayment Status",
      "sql": "SELECT \"Repayment Status\" AS status, COUNT(*) AS count FROM \"shg_loan_register\" GROUP BY 1 ORDER BY 2 DESC",
      "x": "status",
      "y": ["count"]
    },
    {
      "id": "p5",
      "kind": "bar",
      "title": "Loan Amount by Purpose",
      "sql": "SELECT \"Purpose\" AS purpose, SUM(\"Loan Amount (Rs)\") AS total_amount FROM \"shg_loan_register\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10",
